/****************************************************************************
 * Name: r528_bringup
 *
 * Description:
 *   Perform architecture-specific initialization
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=y :
 *     Called from board_late_initialize().
 *
 *   CONFIG_BOARD_LATE_INITIALIZE=n && CONFIG_LIB_BOARDCTL=y :
 *     Called from the NSH library
 *
 ****************************************************************************/
int r528_bringup(void)
{
  int ret = OK;
  int local_ret = OK;

#ifdef CONFIG_FS_PROCFS
  /* Mount the procfs file system */

  ret = mount(NULL, "/proc", "procfs", 0, NULL);
  if (ret < 0)
    {
      syslog(LOG_ERR, "ERROR: Failed to mount procfs at /proc: %d\n", ret);
    }
#endif

#if defined(CONFIG_USERLED) && defined(CONFIG_USERLED_LOWER)
  /* Register the LED driver */
  extern int userled_lower_initialize(FAR const char *devname);
  ret = userled_lower_initialize("/dev/userleds");
  if (ret < 0) {
    syslog(LOG_ERR, "ERROR: userled_lower_initialize() failed: %d\n", ret);
  }
#endif

#ifdef CONFIG_DRIVERS_GPADC
  local_ret = r528_gpadc_initialize("/dev/adc0", 0);
  if (local_ret < 0)
    {
      syslog(LOG_ERR, "ERROR: r528_gpadc_initialize(/dev/adc0) failed: %d\n",
             local_ret);
      if (ret >= 0)
        {
          ret = local_ret;
        }
    }

  local_ret = r528_gpadc_initialize("/dev/adc1", 1);
  if (local_ret < 0)
    {
      syslog(LOG_WARNING,
             "WARNING: r528_gpadc_initialize(/dev/adc1) failed: %d\n",
             local_ret);
    }
#endif

  return ret;
}

