  addr_buf[0] = (regaddr >> 8) & 0xFF;   /* High byte */
  addr_buf[1] = regaddr & 0xFF;          /* Low byte */

  /* Set up the address write operation */
  msg[0].frequency = priv->frequency;
  msg[0].addr      = priv->i2c_addr;
  msg[0].flags     = 0;
  msg[0].buffer    = addr_buf;
