static int gt911_touch_process_data(FAR struct gt911_touch_dev_s *priv,FAR struct touch_sample_s *sample)
{
  FAR struct gt911_touch_data_s *raw = (FAR struct gt911_touch_data_s *)priv->touch_buf;
