/**********************
 *   STATIC FUNCTIONS
 **********************/

static int32_t align_round_up(int32_t v, uint16_t align)
{
    return (v + align - 1) & ~(align - 1);
}

static void * alloc_aligned_draw_buf(size_t buf_size, uint16_t hw_align)
{
    size_t align = LV_DRAW_BUF_ALIGN;

    if(hw_align > align) {
        align = hw_align;
    }

    if(align < sizeof(void *)) {
        align = sizeof(void *);
    }

    return memalign(align, buf_size);
}

static void rounder_cb(lv_event_t * e)
{
    lv_nuttx_lcd_t * lcd = lv_event_get_user_data(e);
    lv_area_t * area = lv_event_get_param(e);
    struct lcddev_area_align_s * align_info = &lcd->align_info;
    uint16_t col_align = align_info->col_start_align ? align_info->col_start_align : 1;
    uint16_t row_align = align_info->row_start_align ? align_info->row_start_align : 1;
    uint16_t width_align = align_info->width_align ? align_info->width_align : 1;
    uint16_t height_align = align_info->height_align ? align_info->height_align : 1;
    int32_t w;
    int32_t h;

    area->x1 &= ~(col_align - 1);
    area->y1 &= ~(row_align - 1);

    w = align_round_up(lv_area_get_width(area), width_align);
    h = align_round_up(lv_area_get_height(area), height_align);

    area->x2 = area->x1 + w - 1;
    area->y2 = area->y1 + h - 1;
}

static void flush_cb(lv_display_t * disp, const lv_area_t * area_p,
                     uint8_t * color_p)
{
    lv_nuttx_lcd_t * lcd = disp->driver_data;

    lcd->area.row_start = area_p->y1;
    lcd->area.row_end = area_p->y2;
    lcd->area.col_start = area_p->x1;
    lcd->area.col_end = area_p->x2;
    lcd->area.data = (uint8_t *)color_p;
    ioctl(lcd->fd, LCDDEVIO_PUTAREA, (unsigned long) & (lcd->area));
    lv_display_flush_ready(disp);
}

static lv_display_t * lcd_init(int fd, int hor_res, int ver_res)
{
    uint8_t * draw_buf = NULL;
    uint8_t * draw_buf_2 = NULL;
    lv_nuttx_lcd_t * lcd = lv_malloc_zeroed(sizeof(lv_nuttx_lcd_t));
    LV_ASSERT_MALLOC(lcd);
    if(lcd == NULL) {
        LV_LOG_ERROR("lv_nuttx_lcd_t malloc failed");
        return NULL;
    }

    lv_display_t * disp = lv_display_create(hor_res, ver_res);
    if(disp == NULL) {
        lv_free(lcd);
        return NULL;
    }

    lcd->fd = fd;
    if(ioctl(fd, LCDDEVIO_GETAREAALIGN, &lcd->align_info) < 0) {
        perror("Error: ioctl(LCDDEVIO_GETAREAALIGN) failed");
        memset(&lcd->align_info, 0, sizeof(lcd->align_info));
    }

    if(lcd->align_info.row_start_align == 0) lcd->align_info.row_start_align = 1;
    if(lcd->align_info.height_align == 0) lcd->align_info.height_align = 1;
    if(lcd->align_info.col_start_align == 0) lcd->align_info.col_start_align = 1;
    if(lcd->align_info.width_align == 0) lcd->align_info.width_align = 1;
    if(lcd->align_info.buf_align == 0) lcd->align_info.buf_align = 1;

    uint32_t px_size = lv_color_format_get_size(lv_display_get_color_format(disp));
#if LV_NUTTX_LCD_BUFFER_COUNT > 0
    uint32_t buf_size = hor_res * ver_res * px_size;
    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_FULL;
#else
    uint32_t buf_size = hor_res * LV_NUTTX_LCD_BUFFER_SIZE * px_size;
    lv_display_render_mode_t render_mode = LV_DISPLAY_RENDER_MODE_PARTIAL;
#endif

    draw_buf = alloc_aligned_draw_buf(buf_size, lcd->align_info.buf_align);
    if(draw_buf == NULL) {
        LV_LOG_ERROR("display draw_buf malloc failed");
        lv_display_delete(disp);
        lv_free(lcd);
        return NULL;
    }

#if LV_NUTTX_LCD_BUFFER_COUNT == 2
    draw_buf_2 = alloc_aligned_draw_buf(buf_size, lcd->align_info.buf_align);
    if(draw_buf_2 == NULL) {
        LV_LOG_ERROR("display draw_buf_2 malloc failed");
        lv_display_delete(disp);
        lv_free(lcd);
        free(draw_buf);
        return NULL;
    }
#endif

    lcd->disp = disp;
    lv_display_set_buffers(lcd->disp, draw_buf, draw_buf_2, buf_size, render_mode);
    lv_display_set_flush_cb(lcd->disp, flush_cb);
    lv_display_add_event_cb(lcd->disp, rounder_cb, LV_EVENT_INVALIDATE_AREA, lcd);
    lv_display_add_event_cb(lcd->disp, display_release_cb, LV_EVENT_DELETE, lcd->disp);
    lv_display_set_driver_data(lcd->disp, lcd);

    return lcd->disp;
}

static void display_release_cb(lv_event_t * e)
{
    lv_display_t * disp = (lv_display_t *) lv_event_get_user_data(e);
    lv_nuttx_lcd_t * dsc = lv_display_get_driver_data(disp);
    if(dsc) {
        lv_display_set_driver_data(disp, NULL);
        lv_display_set_flush_cb(disp, NULL);

        /* clear display buffer */
        if(disp->buf_1 && disp->buf_1->unaligned_data) {
            free(disp->buf_1->unaligned_data);
            disp->buf_1->unaligned_data = NULL;
        }
        if(disp->buf_2 && disp->buf_2->unaligned_data) {
            free(disp->buf_2->unaligned_data);
            disp->buf_2->unaligned_data = NULL;
        }

        /* close device fb */
        if(dsc->fd >= 0) {
            close(dsc->fd);
            dsc->fd = -1;
        }

