static int gt911_detect_controller(FAR struct gt911_touch_dev_s *priv)
{
  uint8_t product_id[4];
  int ret;

  memset(product_id, 0, sizeof(product_id));
  ret = gt911_i2c_read(priv, GT911_REG_PRODUCT_ID, product_id, 4);
  if(ret < 0)
    {
      ierr("fisker: Failed to read GT911 product ID: %d\n", ret);
      return ret;
    }

  if(memcmp(product_id, "911", 3) != 0)
    {
      ierr("fisker: Unexpected GT911 product ID: %02x %02x %02x %02x\n",
           product_id[0], product_id[1], product_id[2], product_id[3]);
      return ERROR_READ;
    }

  return OK;
}

