static int32_t align_round_up(int32_t v, uint16_t align)
{
    return (v + align - 1) & ~(align - 1);
}

static void * alloc_aligned_draw_buf(size_t buf_size, uint16_t hw_align)
{
    size_t align = LV_DRAW_BUF_ALIGN;

    if(hw_align > align) {
        align = hw_align;
    }

    if(align < sizeof(void *)) {
        align = sizeof(void *);
    }

    return memalign(align, buf_size);
}

static void rounder_cb(lv_event_t * e)
{
    lv_nuttx_lcd_t * lcd = lv_event_get_user_data(e);
    lv_area_t * area = lv_event_get_param(e);
    struct lcddev_area_align_s * align_info = &lcd->align_info;
    uint16_t col_align = align_info->col_start_align ? align_info->col_start_align : 1;
    uint16_t row_align = align_info->row_start_align ? align_info->row_start_align : 1;
    uint16_t width_align = align_info->width_align ? align_info->width_align : 1;
    uint16_t height_align = align_info->height_align ? align_info->height_align : 1;
    int32_t w;
    int32_t h;

    area->x1 &= ~(col_align - 1);
    area->y1 &= ~(row_align - 1);

    w = align_round_up(lv_area_get_width(area), width_align);
    h = align_round_up(lv_area_get_height(area), height_align);

    area->x2 = area->x1 + w - 1;
    area->y2 = area->y1 + h - 1;
}

