   328	    switch(priv->last_state){
   329	
   330	      case TOUCH_INVALID:
   331	
   332	        sample->point[0].flags |= TOUCH_DOWN;
   333	        priv->last_state = TOUCH_VALID;
   334	        touch_event(priv->lower.priv, sample);
